import projectsMeta from './projects-meta.json'

export const PROJECT_ASSET_FOLDER_MAP = {
  musicbuddy: 'musicBuddy',
  healthyexpert: 'healthyExpert',
  birdwatching: 'birdWatching',
  trafistats: 'trafiStats',
  ewaste: 'ewaste',
  haonengjia: 'haonengjia',
  alcocalc: 'alcoCalc',
  jofind: 'joFind',
  netify: 'netify',
  whattomix: 'whatToMix',
  thebigwalk: 'theBigWalk',
  meowid: 'meowID'
}

const PROJECT_COVER_IMAGE_MAP = {
  musicbuddy: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.musicbuddy}/cover.webp`),
  healthyexpert: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.healthyexpert}/cover.webp`),
  birdwatching: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.birdwatching}/cover.webp`),
  trafistats: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.trafistats}/cover.webp`),
  ewaste: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.ewaste}/cover.webp`),
  haonengjia: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.haonengjia}/cover.webp`),
  alcocalc: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.alcocalc}/cover.webp`),
  jofind: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.jofind}/cover.webp`),
  netify: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.netify}/cover.webp`),
  whattomix: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.whattomix}/cover.webp`),
  thebigwalk: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.thebigwalk}/cover.webp`),
  meowid: require(`@/assets/project/${PROJECT_ASSET_FOLDER_MAP.meowid}/cover.webp`)
}

export const PROJECTS = projectsMeta.map((item) => {
  const mapped = PROJECT_COVER_IMAGE_MAP[item.slug]
  const image = mapped?.default || mapped || item.image
  return {
    ...item,
    image
  }
})

export const getProjectBySlug = (slug) => PROJECTS.find((item) => item.slug === slug)
