<template>
  <ProjectAssetDetailView
    v-if="project"
    :project="project"
    :hero-image="heroImage"
    :screenshots="screenshots"
    :copy="copy"
  />
</template>

<script>
import ProjectAssetDetailView from '@/components/projects/ProjectAssetDetailView.vue'
import { getProjectBySlug, PROJECT_ASSET_FOLDER_MAP } from '@/data/projects'
import { DEFAULT_PROJECT_COPY, PROJECT_DETAIL_COPY } from '@/data/project-detail'
import { getProjectAssetImagesByFolder } from '@/utils/projectAssets'

const allProjectImagesContext = require.context('../assets/project', true, /\.(png|jpe?g|webp|svg)$/)

export default {
  name: 'ProjectDetailView',
  components: { ProjectAssetDetailView },
  data() {
    return {
      project: null,
      heroImage: '',
      screenshots: [],
      copy: DEFAULT_PROJECT_COPY
    }
  },
  watch: {
    '$route.params.slug': {
      immediate: true,
      handler() {
        this.bindProjectData()
      }
    }
  },
  methods: {
    normalizeImageSrc(image) {
      return image?.default || image || ''
    },
    getCustomGallery(copy) {
      if (!copy || !Array.isArray(copy.gallery) || !copy.gallery.length) return null

      return copy.gallery.map((item) => this.normalizeImageSrc(item)).filter(Boolean)
    },
    bindProjectData() {
      const slug = this.$route.params.slug
      const project = getProjectBySlug(slug)

      if (!project) {
        this.$router.replace('/projects')
        return
      }

      const folder = PROJECT_ASSET_FOLDER_MAP[slug]
      const { heroImage, screenshots: autoScreenshots } = getProjectAssetImagesByFolder(allProjectImagesContext, folder)
      const copy = PROJECT_DETAIL_COPY[slug] || DEFAULT_PROJECT_COPY
      const customGallery = this.getCustomGallery(copy)

      this.project = project
      this.heroImage = heroImage
      this.screenshots = customGallery || autoScreenshots
      this.copy = copy
    }
  }
}
</script>
