const kittyContext = require.context('../assets/kitty', false, /\.webp$/)
const motorbikeContext = require.context('../assets/motorbike', false, /\.webp$/)

const parseKittyDateFromPath = (path) => {
  const fileName = (path.split('/').pop() || '').replace('.webp', '')
  if (!/^\d{6}$/.test(fileName)) return fileName
  return `20${fileName.slice(0, 2)}-${fileName.slice(2, 4)}-${fileName.slice(4, 6)}`
}

const getFileNameFromPath = (path) => (path.split('/').pop() || '').replace('.webp', '')

export const CAT_PHOTOS = kittyContext
  .keys()
  .sort((aPath, bPath) => bPath.localeCompare(aPath))
  .map((path, index) => {
    const module = kittyContext(path)
    const url = module.default || module
    const date = parseKittyDateFromPath(path)
    return {
      id: index + 1,
      url,
      caption: date,
      date: ''
    }
  })

