export const MOTORCYCLE_PHOTOS = motorbikeContext
  .keys()
  .sort((aPath, bPath) => bPath.localeCompare(aPath))
  .map((path, index) => {
    const module = motorbikeContext(path)
    const url = module.default || module
    const fileName = getFileNameFromPath(path)
    return {
      id: index + 1,
      url,
      caption: fileName,
      date: ''
    }
  })

