  <section v-if="project" class="section project-detail-page">
    <button class="project-back" type="button" @click="$router.push('/projects')">返回项目列表</button>

    <div class="project-hero neo-frame" :style="{ background: project.color }">
      <img
        class="project-hero-image"
        :src="project.image || heroImage"
        :alt="project.title"
        loading="lazy"
        decoding="async"
        referrerpolicy="no-referrer"
      />
    </div>

    <h1 class="project-title">{{ project.title }}</h1>

    <div class="project-meta">
      <HighlightTag bg-color="#fff" text-color="#0f172a" padding="6px 10px" border="2px solid #000" font-size="12px" font-weight="800">
        {{ project.date }}
      </HighlightTag>
      <HighlightTag bg-color="#fff" text-color="#0f172a" padding="6px 10px" border="2px solid #000" font-size="12px" font-weight="800">
        {{ project.role }}
      </HighlightTag>
      <HighlightTag bg-color="#fff" text-color="#0f172a" padding="6px 10px" border="2px solid #000" font-size="12px" font-weight="800">
        {{ project.tools }}
      </HighlightTag>
    </div>

    <p class="project-lead">
      {{ copy.lead }}
    </p>

    <section class="project-section">
      <h2 class="project-section-title">{{ copy.sectionTitle }}</h2>
      <div class="project-prose">
        <p v-for="(paragraph, idx) in copy.sectionParagraphs" :key="`${paragraph}-${idx}`">{{ paragraph }}</p>
      </div>
    </section>

    <template v-for="(sec, sidx) in richSections" :key="`rich-${sidx}-${sec.title}`">
      <section class="project-section project-rich-section">
        <h2 class="project-section-title">{{ sec.title }}</h2>

        <div v-if="sec.kind === 'blocks'" class="project-rich-blocks">
          <article
            v-for="(block, bidx) in sec.blocks"
            :key="`b-${bidx}-${block.header}`"
            class="project-rich-block neo-frame neo-frame-panel"
          >
            <h3 class="project-rich-block-title">{{ block.header }}</h3>
            <ul v-if="block.descriptions && block.descriptions.length" class="project-rich-list">
              <li v-for="(d, didx) in block.descriptions" :key="`d-${didx}`">{{ d }}</li>
            </ul>
            <p v-else-if="block.body" class="project-rich-body">{{ block.body }}</p>
          </article>
        </div>

        <div v-else-if="sec.kind === 'prose'" class="project-prose">
          <p v-for="(p, pidx) in sec.paragraphs" :key="`p-${pidx}`">{{ p }}</p>
        </div>

        <div v-else-if="sec.kind === 'paragraphList'" class="project-prose project-paragraph-list">
          <p>{{ sec.paragraph }}</p>
          <ul class="project-list">
            <li v-for="(li, liidx) in sec.listItems" :key="`li-${liidx}`">{{ li }}</li>
          </ul>
        </div>

        <div v-else-if="sec.kind === 'subsections'" class="project-rich-subsections">
          <article
            v-for="(sub, subidx) in sec.items"
            :key="`sub-${subidx}`"
            :class="[
              'project-subsection',
              'neo-frame',
              'neo-frame-panel',
              {
                'project-subsection--reverse': sub.image && subidx % 2 === 1,
                'project-subsection--text-only': !sub.image
              }
            ]"
          >
            <div v-if="sub.image" class="project-subsection-media">
              <img
                class="project-subsection-image"
                :src="resolveImage(sub.image)"
                :alt="sub.header || `${project.title}-section-${subidx + 1}`"
                loading="lazy"
                decoding="async"
                referrerpolicy="no-referrer"
