              <p class="project-subsection-body">{{ sub.content }}</p>
            </div>
          </article>
        </div>

        <div v-else-if="sec.kind === 'kvTable'" class="project-kv-wrap">
          <dl class="project-kv">
            <template v-for="(row, ridx) in sec.rows" :key="`kv-${ridx}`">
              <dt>{{ row.label }}</dt>
              <dd>{{ row.value }}</dd>
            </template>
          </dl>
        </div>

        <div v-else-if="sec.kind === 'roleBlocks'" class="project-role-blocks">
          <article
            v-for="(roleBlock, ridx) in sec.roles"
            :key="`role-${ridx}`"
            class="project-role-block neo-frame neo-frame-panel"
          >
            <h3 class="project-role-title">{{ roleBlock.role }}</h3>
            <ul class="project-rich-list">
              <li v-for="(ab, abidx) in roleBlock.abilities" :key="`ab-${abidx}`">{{ ab }}</li>
            </ul>
          </article>
        </div>

        <div v-else-if="sec.kind === 'feedbackGroups'" class="project-rich-blocks">
          <article
            v-for="(g, gidx) in sec.groups"
            :key="`fg-${gidx}`"
            class="project-rich-block neo-frame neo-frame-panel"
          >
            <h3 class="project-rich-block-title">{{ g.header }}</h3>
            <ul v-if="g.comments && g.comments.length" class="project-rich-list">
              <li v-for="(c, cidx) in g.comments" :key="`c-${cidx}`">{{ c }}</li>
            </ul>
          </article>
        </div>

        <blockquote v-else-if="sec.kind === 'quote'" class="project-quote neo-frame neo-frame-panel">
          <p>{{ sec.text }}</p>
        </blockquote>

        <div v-else-if="sec.kind === 'award'" class="project-award neo-frame neo-frame-panel">
          <h3 class="project-rich-block-title">{{ sec.name }}</h3>
          <p class="project-rich-body">{{ sec.content }}</p>
        </div>

        <div v-else-if="sec.kind === 'proseAndRoleBlocks'">
          <div class="project-prose">
            <p v-for="(p, pidx) in sec.paragraphs" :key="`pr-${pidx}`">{{ p }}</p>
