              <ul class="project-rich-list">
                <li v-for="(ab, abidx) in roleBlock.abilities" :key="`pab-${abidx}`">{{ ab }}</li>
              </ul>
            </article>
          </div>
        </div>
      </section>
    </template>

    <div v-if="copy.cards && copy.cards.length" class="project-card-grid">
      <article v-for="(card, idx) in copy.cards" :key="`${card.title}-${idx}`" class="project-card neo-frame neo-frame-panel">
        <h3 class="project-card-title">{{ card.title }}</h3>
        <p class="project-card-body">{{ card.body }}</p>
      </article>
    </div>

    <section v-if="copy.principles && copy.principles.length" class="project-section">
      <h2 class="project-section-title">关键原则</h2>
      <ul class="project-list">
        <li v-for="(principle, idx) in copy.principles" :key="`${principle}-${idx}`">{{ principle }}</li>
      </ul>
    </section>

    <section class="project-gallery">
      <h2 class="project-section-title">项目截图</h2>
      <div class="project-gallery-grid">
        <div v-for="(src, idx) in screenshots" :key="`${src}-${idx}`" class="project-gallery-item neo-frame neo-frame-panel">
          <img
            class="project-gallery-image"
            :src="src"
            :alt="`${project.title}-${idx + 1}`"
            loading="lazy"
            decoding="async"
            referrerpolicy="no-referrer"
          />
        </div>
      </div>
    </section>
  </section>
</template>

<script>
import HighlightTag from '@/components/common/HighlightTag.vue'

export default {
  name: 'ProjectAssetDetailView',
  components: { HighlightTag },
  props: {
    project: {
      type: Object,
      required: true
    },
    heroImage: {
      type: String,
      required: true
    },
    screenshots: {
      type: Array,
      default: () => []
    },
    copy: {
      type: Object,
      required: true
    }
  },
  computed: {
    richSections() {
      return this.copy.richSections || []
    }
  },
  methods: {
    resolveImage(image) {
      return image?.default || image || ''
    }
  }
}
</script>

