const SITE_NAME = 'Terence'
const SITE_URL = 'https://terenzzzz.cn'
const DEFAULT_TITLE = 'Terence | 个人网站'
const DEFAULT_DESCRIPTION = 'Terence 的个人网站，记录开发过的项目、日常兴趣爱好，以及设计与开发相关的实践。'
const DEFAULT_TYPE = 'website'
const DEFAULT_IMAGE = '/favicon.ico'

const PERSON_SCHEMA = {
  '@context': 'https://schema.org',
  '@type': 'Person',
  name: 'Terence',
  url: SITE_URL,
  email: 'mailto:terence592592@gmail.com',
  sameAs: [
    'https://github.com/terenzzzz',
    'https://instagram.com/terenzzzz_'
  ]
}

function getOrigin() {
  if (typeof window === 'undefined') return SITE_URL

  const { origin, hostname } = window.location
  if (hostname === 'localhost' || hostname === '127.0.0.1') {
    return SITE_URL
  }

  return origin
}

function toAbsoluteUrl(value) {
  if (!value) return `${getOrigin()}${DEFAULT_IMAGE}`
  if (/^https?:\/\//.test(value)) return value
  return `${getOrigin()}${value.startsWith('/') ? value : `/${value}`}`
}

function upsertMeta(selector, attrs) {
  let tag = document.head.querySelector(selector)
  if (!tag) {
    tag = document.createElement('meta')
    document.head.appendChild(tag)
  }

  Object.entries(attrs).forEach(([key, value]) => {
    tag.setAttribute(key, value)
  })
}

function upsertLink(selector, attrs) {
  let tag = document.head.querySelector(selector)
  if (!tag) {
    tag = document.createElement('link')
    document.head.appendChild(tag)
  }

  Object.entries(attrs).forEach(([key, value]) => {
    tag.setAttribute(key, value)
  })
}

function upsertStructuredData(schema) {
  let tag = document.head.querySelector('script[data-seo-schema]')
  if (!tag) {
    tag = document.createElement('script')
    tag.type = 'application/ld+json'
    tag.setAttribute('data-seo-schema', 'true')
    document.head.appendChild(tag)
  }

  tag.textContent = JSON.stringify(schema)
}

export function applyRouteSeo(route) {
  const meta = route.meta || {}
  const title = meta.title || DEFAULT_TITLE
  const description = meta.description || DEFAULT_DESCRIPTION
  const type = meta.ogType || DEFAULT_TYPE
  const image = toAbsoluteUrl(meta.image || DEFAULT_IMAGE)
  const canonicalUrl = `${getOrigin()}${route.fullPath || '/'}`

  document.title = title

  upsertMeta('meta[name="description"]', { name: 'description', content: description })
  upsertMeta('meta[name="robots"]', { name: 'robots', content: 'index,follow' })
  upsertMeta('meta[property="og:type"]', { property: 'og:type', content: type })
  upsertMeta('meta[property="og:site_name"]', { property: 'og:site_name', content: SITE_NAME })
  upsertMeta('meta[property="og:locale"]', { property: 'og:locale', content: 'zh_CN' })
  upsertMeta('meta[property="og:title"]', { property: 'og:title', content: title })
  upsertMeta('meta[property="og:description"]', { property: 'og:description', content: description })
  upsertMeta('meta[property="og:url"]', { property: 'og:url', content: canonicalUrl })
  upsertMeta('meta[property="og:image"]', { property: 'og:image', content: image })
  upsertMeta('meta[name="twitter:card"]', { name: 'twitter:card', content: 'summary_large_image' })
  upsertMeta('meta[name="twitter:title"]', { name: 'twitter:title', content: title })
  upsertMeta('meta[name="twitter:description"]', { name: 'twitter:description', content: description })
  upsertMeta('meta[name="twitter:image"]', { name: 'twitter:image', content: image })
  upsertLink('link[rel="canonical"]', { rel: 'canonical', href: canonicalUrl })

  upsertStructuredData({
    '@context': 'https://schema.org',
    '@graph': [
      PERSON_SCHEMA,
      {
        '@type': meta.schemaType || 'WebPage',
        name: title,
        description,
        url: canonicalUrl,
        image
      }
    ]
  })
}
