<script>
import PhotoGrid from '@/components/gallery/PhotoGrid.vue'
import motorcycleImg from '@/assets/images/motorcycle.webp'
import { MOTORCYCLE_PHOTOS, MOTORCYCLE_SPECS } from '@/data/siteData'

export default {
  name: 'MotorcyclesView',
  components: { PhotoGrid },
  data() {
    return {
      photos: MOTORCYCLE_PHOTOS,
      specs: MOTORCYCLE_SPECS,
      motorcycleImg
    }
  },
  computed: {
    modelName() {
      return this.specs.find((item) => item.label === '型号')?.value || 'MOTORCYCLE'
    },
    makerName() {
      return 'HONDA'
    },
    specVersion() {
      const year = this.specs.find((item) => item.label === '年份')?.value
      return year ? `${year}.04` : '2025.04'
    }
  }
}
