<template>
  <div ref="mapEl" class="travel-map"></div>
</template>

<script>
import { onBeforeUnmount, onMounted, ref } from 'vue'
import L from 'leaflet'
import avatarImg from '@/assets/images/avatar.webp'
import { TRAVEL_LOCATIONS, TRAVEL_MAP_INITIAL_VIEW } from '@/data/travelLocations'

export default {
  name: 'TravelMap',
  setup() {
    const mapEl = ref(null)
    let map = null

    onMounted(() => {
      map = L.map(mapEl.value, {
        zoomControl: true,
        minZoom: 2,
        maxZoom: 18
      }).setView(TRAVEL_MAP_INITIAL_VIEW.center, TRAVEL_MAP_INITIAL_VIEW.zoom)

      L.tileLayer("https://webrd04.is.autonavi.com/appmaptile?lang=zh_cn&size=1&scale=1&style=7&x={x}&y={y}&z={z}", {
        subdomains: ['1', '2', '3', '4'],
        attribution: '&copy; 高德地图',
        detectRetina: true
      }).addTo(map)

      const redIcon = L.divIcon({
        html: `
          <div class="custom-featured-marker">
            <img loading="lazy" src="${avatarImg}" alt="avatar" />
          </div>
        `,
        className: '',
        iconSize: [50, 50],
        iconAnchor: [25, 50],
        popupAnchor: [0, -45]
      })

      const CustomDivControl = L.Control.extend({
        onAdd() {
          const customDiv = L.DomUtil.create('div', 'base custom-city-control')
          customDiv.innerHTML = `
            <div class="city-card">
              <p>广州, 中国</p>
            </div>
          `
          return customDiv
        }
      })

      const customDiv = new CustomDivControl({ position: 'bottomleft' })
      customDiv.addTo(map)

      TRAVEL_LOCATIONS.forEach((loc) => {
        if (loc.featured) {
          L.marker(loc.coords, { icon: redIcon, zIndexOffset: 1000 }).addTo(map).bindTooltip(loc.name, { direction: 'top' })
          return
        }

        L.circleMarker(loc.coords, {
          radius: 4.5,
          color: '#0f172a',
          weight: 1.5,
          fillColor: '#4D61FC',
          fillOpacity: 0.95
        }).addTo(map).bindTooltip(loc.name, { direction: 'top' })
      })
    })

    onBeforeUnmount(() => {
      if (map) {
        map.remove()
        map = null
      }
    })

    return {
      mapEl
    }
  }
}
</script>

