<template>
  <section class="section cocktails-page">
    <header class="header dark neo-frame">
      <div class="left">
        <HighlightTag
          class="badge"
          bg-color="#f472b6"
          text-color="#fff"
          padding="6px 10px"
          font-size="10px"
          font-weight="900"
          letter-spacing="0.16em"
          text-transform="uppercase"
        >
          COCKTAIL NOTES
        </HighlightTag>
        <h1>鸡尾酒 <HighlightTag bg-color="#fde047">笔记</HighlightTag></h1>
        <div class="metrics">
          <div><strong>{{ tastingCount }}</strong><small>已品鉴</small></div>
          <div><strong>{{ cityCount }}</strong><small>城市</small></div>
        </div>
      </div>
      <div class="flavor neo-frame neo-frame-panel">
        <h3>口味偏好</h3>
        <div class="bars">
          <div v-for="item in profile" :key="item.label" class="bar-row">
            <div class="meta"><span>{{ item.label }}</span><span>{{ item.val }}</span></div>
            <div class="track"><div class="fill" :style="{ width: item.val, background: item.color }"></div></div>
          </div>
        </div>
      </div>
    </header>
    <div class="gallery-divider" aria-hidden="true">
      <span class="gallery-divider-title">COCKTAIL LOGS</span>
      <span class="gallery-divider-line"></span>
      <span class="gallery-divider-meta">GALLERY_VIEW_01</span>
    </div>
    <PhotoGrid :photos="photos" />
  </section>
</template>

<script>
import HighlightTag from '@/components/common/HighlightTag.vue'
import PhotoGrid from '@/components/gallery/PhotoGrid.vue'
import { COCKTAIL_PHOTOS } from '@/data/siteData'

export default {
  name: 'CocktailsView',
  components: { HighlightTag, PhotoGrid },
  data() {
    return {
      photos: COCKTAIL_PHOTOS,
      profile: [
        { label: '苦度', val: '40%', color: '#f472b6' },
        { label: '酸度', val: '70%', color: '#fde047' },
        { label: '甜度', val: '40%', color: '#4D61FC' },
        { label: '烈度', val: '30%', color: '#111827' }
      ]
    }
  },
  computed: {
    tastingCount() {
      return this.photos.length
    },
    cityCount() {
      const cities = new Set(
        this.photos
          .map((item) => item.city)
          .filter(Boolean)
      )
      return cities.size
    }
  }
}
</script>

